/**
 * Genera un bioma estilo valle Fortnite (Chapter 2 Island):
 * - Colinas verdes onduladas y suaves con picos rocosos/nevados aislados.
 * - Ríos serpenteantes en los valles con orillas de arena y grava.
 * - Caminos de tierra/grava y dos tipos de árboles (robles redondeados y pinos cónicos).
 * - Praderas densas con flores rojas, amarillas y hierba alta.
 */
async function buildFortniteValley(originX = 0, originY = 0, originZ = 0, options = {}) {
    const mapWidth = options.mapWidth || 128;
    const mapHeight = options.mapHeight || 44;
    const mapDepth = options.mapDepth || 128;
    const seaLevel = options.seaLevel || 10;
    const snowLine = options.snowLine || 34;

    // Materiales del catálogo de assets
    const grassMat = options.grassMat || 'hierba';
    const dirtMat = options.dirtMat || 'tierra';
    const rockMat = options.rockMat || 'roca';
    const cobbleMat = options.cobbleMat || 'adoquin';
    const sandMat = options.sandMat || 'arena';
    const gravelMat = options.gravelMat || 'grava';
    const waterMat = options.waterMat || 'agua';
    const snowMat = options.snowMat || 'nieve';
    const logMat = options.logMat || 'tronco';
    const leafMat = options.leafMat || 'leaves';
    const yellowFlower = options.yellowFlower || 'flor-amarilla';
    const redFlower = options.redFlower || 'flor-roja';
    const tallGrass = options.tallGrass || 'hierba-alta';
    const bedrockMat = options.bedrockMat || 'obsidiana';

    if (typeof game !== 'undefined' && game.addMaterial) {
        await Promise.all([
            game.addMaterial(grassMat).catch(() => null),
            game.addMaterial(dirtMat).catch(() => null),
            game.addMaterial(rockMat).catch(() => null),
            game.addMaterial(cobbleMat).catch(() => null),
            game.addMaterial(sandMat).catch(() => null),
            game.addMaterial(gravelMat).catch(() => null),
            game.addMaterial(waterMat).catch(() => null),
            game.addMaterial(snowMat).catch(() => null),
            game.addMaterial(logMat).catch(() => null),
            game.addMaterial(leafMat).catch(() => null),
            game.addMaterial(yellowFlower).catch(() => null),
            game.addMaterial(redFlower).catch(() => null),
            game.addMaterial(tallGrass).catch(() => null),
            game.addMaterial(bedrockMat).catch(() => null)
        ]);
    }

    if (typeof beginBatch === 'function') beginBatch();

    // 1. ELEVACIÓN TOPOGRÁFICA (Colinas suaves + meandro fluvial)
    function getTerrainHeight(x, z) {
        const fx = x * 0.028;
        const fz = z * 0.028;

        // Ondulaciones amplias y suaves (Rolling hills)
        const baseHills = Math.sin(fx) * 0.55 + Math.cos(fz) * 0.55;
        const subHills = Math.sin(fx * 2.1 + fz * 1.7) * 0.25;
        const microDetail = Math.cos(fx * 4.2 - fz * 3.8) * 0.08;

        let combined = (baseHills + subHills + microDetail + 1.4) / 2.8;

        // Pico montañoso destacado en un extremo
        const distToPeak = Math.hypot(x - mapWidth * 0.82, z - mapDepth * 0.82);
        if (distToPeak < 35) {
            const peakFactor = Math.pow(Math.max(0, 1 - distToPeak / 35), 2);
            combined += peakFactor * 0.65;
        }

        let height = Math.floor(6 + combined * (mapHeight - 10));

        // Trazado del río sinuoso (meandro en S a través del mapa)
        const riverCenterZ = mapDepth * 0.45 + Math.sin(x * 0.05) * 16 + Math.cos(x * 0.02) * 8;
        const distToRiver = Math.abs(z - riverCenterZ);

        if (distToRiver < 8) {
            const riverCarve = Math.cos((distToRiver / 8) * (Math.PI / 2));
            const riverBedY = seaLevel - 2;
            height = Math.floor(height * (1 - riverCarve) + riverBedY * riverCarve);
        }

        return { height, distToRiver };
    }

    const plantedTrees = [];

    // 2. CONSTRUCCIÓN DE CAPAS Y VOLUMEN
    for (let x = 0; x < mapWidth; x++) {
        for (let z = 0; z < mapDepth; z++) {
            const { height: surfaceY, distToRiver } = getTerrainHeight(x, z);

            const hRight = getTerrainHeight(Math.min(x + 1, mapWidth - 1), z).height;
            const hForward = getTerrainHeight(x, Math.min(z + 1, mapDepth - 1)).height;
            const slope = Math.abs(surfaceY - hRight) + Math.abs(surfaceY - hForward);

            const isRiverBank = distToRiver >= 3.5 && distToRiver <= 6.5 && surfaceY <= seaLevel + 1;
            const isRoad = (Math.abs(z - (mapDepth * 0.2 + x * 0.6)) < 1.8 || Math.abs(x - (mapWidth * 0.5 + Math.sin(z * 0.08) * 4)) < 1.5) && surfaceY > seaLevel + 1 && slope < 3;

            for (let y = 0; y <= Math.max(surfaceY, seaLevel); y++) {
                const gx = originX + x;
                const gy = originY + y;
                const gz = originZ + z;

                if (y > surfaceY && y <= seaLevel) {
                    setVoxel(gx, gy, gz, waterMat);
                } else if (y <= surfaceY) {
                    let mat = rockMat;

                    if (y === surfaceY) {
                        if (y <= seaLevel - 1) {
                            mat = gravelMat; // Lecho del río
                        } else if (isRiverBank) {
                            mat = sandMat; // Playa fluvial
                        } else if (isRoad) {
                            mat = gravelMat; // Camino / sendero
                        } else if (y >= snowLine && slope < 3) {
                            mat = snowMat; // Cumbre nevada
                        } else if (slope >= 4) {
                            mat = (slope >= 6) ? rockMat : cobbleMat; // Escarpados rocosos
                        } else {
                            mat = grassMat; // Césped vibrante
                        }
                    } else if (y >= surfaceY - 3) {
                        mat = (surfaceY <= seaLevel || isRiverBank) ? sandMat : dirtMat;
                    } else {
                        mat = (y === 0) ? bedrockMat : rockMat;
                    }

                    setVoxel(gx, gy, gz, mat);
                }
            }

            // 3. VEGETACIÓN: PINOS CÓNICOS, ROBLES Y FLORES
            const isPlainGrass = surfaceY > seaLevel + 1 && surfaceY < snowLine - 2 && slope < 3 && !isRoad && !isRiverBank;

            if (isPlainGrass) {
                const rng = Math.abs(Math.sin(x * 12.9898 + z * 78.233)) * 43758.5453;
                const val = rng - Math.floor(rng);
                const topY = originY + surfaceY + 1;

                // Plantado de árboles con separación mínima de 6 bloques
                if (val < 0.035 && x >= 5 && x < mapWidth - 5 && z >= 5 && z < mapDepth - 5) {
                    const tooClose = plantedTrees.some(t => {
                        const dx = t.x - x, dz = t.z - z;
                        return (dx * dx + dz * dz) < 36;
                    });

                    if (!tooClose) {
                        plantedTrees.push({ x, z });

                        const isPine = (x + z) % 2 === 0;

                        if (isPine) {
                            // PINO ESTILO FORTNITE (Cónico escalonado)
                            const trunkH = 6 + (Math.floor(val * 100) % 3);
                            for (let th = 0; th < trunkH; th++) {
                                setVoxel(originX + x, topY + th, originZ + z, logMat);
                            }

                            // Follaje en capas cónicas
                            const leafTop = topY + trunkH;
                            setVoxel(originX + x, leafTop + 1, originZ + z, leafMat);

                            const layers = [
                                { r: 1, yOff: 0 },
                                { r: 2, yOff: -1 },
                                { r: 1, yOff: -2 },
                                { r: 3, yOff: -3 },
                                { r: 2, yOff: -4 }
                            ];

                            for (const layer of layers) {
                                const ly = leafTop + layer.yOff;
                                for (let ox = -layer.r; ox <= layer.r; ox++) {
                                    for (let oz = -layer.r; oz <= layer.r; oz++) {
                                        if (Math.abs(ox) === layer.r && Math.abs(oz) === layer.r) continue;
                                        if (ox === 0 && oz === 0 && layer.yOff < 0) continue;
                                        setVoxel(originX + x + ox, ly, originZ + z + oz, leafMat);
                                    }
                                }
                            }
                        } else {
                            // ROBLE ESTILO FORTNITE (Copa densa y redondeada)
                            const trunkH = 4 + (Math.floor(val * 50) % 2);
                            for (let th = 0; th < trunkH; th++) {
                                setVoxel(originX + x, topY + th, originZ + z, logMat);
                            }

                            const leafBase = topY + trunkH - 1;
                            for (let ox = -2; ox <= 2; ox++) {
                                for (let oz = -2; oz <= 2; oz++) {
                                    for (let oy = 0; oy <= 2; oy++) {
                                        if (Math.abs(ox) === 2 && Math.abs(oz) === 2 && oy !== 1) continue;
                                        if (ox === 0 && oz === 0 && oy < 2) continue;
                                        setVoxel(originX + x + ox, leafBase + oy, originZ + z + oz, leafMat);
                                    }
                                }
                            }
                        }
                    }
                }
                // Dispersión de flores y hierba alta
                else if (val > 0.94) {
                    setVoxel(originX + x, topY, originZ + z, yellowFlower);
                } else if (val > 0.91) {
                    setVoxel(originX + x, topY, originZ + z, redFlower);
                } else if (val > 0.85) {
                    setVoxel(originX + x, topY, originZ + z, tallGrass);
                }
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();
}

// --------------------------------------------------------------------------
// EJECUCIÓN Y GENERACIÓN DE ENTORNO
// --------------------------------------------------------------------------
await game.wipeMap();
await game.resizeWorld(128, 44, 128);

console.log("Generando Valle Estilo Fortnite...");
await buildFortniteValley(0, 0, 0, {
    grassMat: "hierba",
    dirtMat: "tierra",
    rockMat: "roca",
    cobbleMat: "adoquin",
    sandMat: "arena",
    gravelMat: "grava",
    waterMat: "agua",
    snowMat: "nieve",
    logMat: "tronco",
    leafMat: "leaves",
    yellowFlower: "flor-amarilla",
    redFlower: "flor-roja",
    tallGrass: "hierba-alta",
    bedrockMat: "obsidiana",
    seaLevel: 10,
    snowLine: 34
});

console.log("Añadiendo nubes...");
game.snippet("nubes-altas");
console.log("Valle completado.");
